findings.fix:
Wrap startOutboxRelay's loop body in a defer/recover that logs and continues. Pattern:

  func startOutboxRelay(...) {
    defer func() {
      if r := recover(); r != nil {
        slog.Error("outbox relay: panic", "panic", r, "stack", string(debug.Stack()))
        // Optional: restart self after backoff, or rely on operator alert
      }
    }()
    ticker := ...
    for { ... }
  }

For a longer-lived guarantee, also wrap relayTick's body so a single bad row doesn't tear down the whole loop:

  case <-ticker.C:
    func() {
      defer func() {
        if r := recover(); r != nil {
          slog.Error("outbox relay: tick panic", "panic", r)
        }
      }()
      if err := relayTick(...); err != nil { ... }
    }()
